-- Report ID : RPT_081
-- Report    : Substitute Report
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                       AS report_date,     pim.DEPT                                             AS dept_no,     d.DEPT_NAME                                          AS dept_name,     pim.CLASS                                            AS class_no,     c.CLASS_NAME                                         AS class_name,     pim.SUBCLASS                                         AS subclass_no,     sc.SUB_NAME                                          AS subclass_name,     sd.ITEM                                              AS primary_item_id,     pim.ITEM_DESC                                        AS primary_item_desc,     pim.STANDARD_UOM                                     AS primary_uom,     pim.STATUS                                           AS primary_item_status,     pim.PACK_IND                                         AS primary_pack,           pils.STOCK_ON_HAND                                   AS primary_item_soh,     pils.AV_COST                                         AS primary_item_wac,     pil.SELLING_UNIT_RETAIL                              AS primary_item_retail,     pil.STATUS                                           AS primary_item_loc_status,     CASE pil.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS primary_item_loc_status_desc,     sd.SUB_ITEM                                          AS sub_item_id,     sim.ITEM_DESC                                        AS sub_item_desc,     sim.STANDARD_UOM                                     AS sub_item_uom,     sim.STATUS                                           AS sub_item_status,     sim.DEPT                                             AS sub_item_dept,     sim.CLASS                                            AS sub_item_class,     sils.STOCK_ON_HAND                                   AS sub_item_soh,     sils.AV_COST                                         AS sub_item_wac,     sil.SELLING_UNIT_RETAIL                              AS sub_item_retail,     sil.STATUS                                           AS sub_item_loc_status,     CASE sil.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS sub_item_loc_status_desc,     sd.LOCATION                                          AS location_id,     sd.LOC_TYPE                                          AS loc_type,     CASE sd.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                  AS loc_type_desc,     CASE sd.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS location_name,     sd.START_DATE                                        AS sub_start_date,     sd.END_DATE                                          AS sub_end_date,     TRUNC(SYSDATE) - TRUNC(NVL(sd.START_DATE, SYSDATE)) AS days_active,     TRUNC(NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999))         - TRUNC(SYSDATE)                                 AS days_remaining,     CASE         WHEN TRUNC(SYSDATE) BETWEEN              NVL(sd.START_DATE, TRUNC(SYSDATE))              AND NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999)         THEN 'ACTIVE'         WHEN TRUNC(SYSDATE) < NVL(sd.START_DATE, TRUNC(SYSDATE))         THEN 'FUTURE'         ELSE 'EXPIRED'     END                                                  AS sub_record_status,     CASE         WHEN sd.END_DATE IS NOT NULL              AND sd.END_DATE BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + 7         THEN 'EXPIRING IN 7 DAYS'         WHEN sd.END_DATE IS NOT NULL              AND sd.END_DATE BETWEEN TRUNC(SYSDATE) + 8 AND TRUNC(SYSDATE) + 30         THEN 'EXPIRING IN 30 DAYS'         WHEN sd.END_DATE IS NULL         THEN 'NO EXPIRY SET'         ELSE 'VALID'     END                                                  AS expiry_urgency,     sd.SUBSTITUTE_REASON                                 AS substitute_reason,     CASE sd.SUBSTITUTE_REASON         WHEN 'O' THEN 'Out of Stock'         WHEN 'D' THEN 'Discontinued'         WHEN 'S' THEN 'Seasonal Replacement'         WHEN 'P' THEN 'Promotional Substitute'         ELSE NVL(sd.SUBSTITUTE_REASON, 'Not Specified')     END                                                  AS substitute_reason_desc,     sd.PICK_PRIORITY                                     AS pick_priority,     ril.REPL_METHOD                                      AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'F'  THEN 'Floating Point'         ELSE NVL(ril.REPL_METHOD, 'NOT ON REPLENISHMENT')     END                                                  AS repl_method_desc,     ril.STOCK_CAT                                        AS stock_category,     ril.REPL_ORDER_CTRL                                  AS order_control,     ril.SOURCE_WH                                        AS source_warehouse,     sril.REPL_METHOD                                     AS sub_repl_method,     CASE sril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'F'  THEN 'Floating Point'         ELSE NVL(sril.REPL_METHOD, 'NOT ON REPLENISHMENT')     END                                                  AS sub_repl_method_desc,     CASE         WHEN NVL(sils.STOCK_ON_HAND, 0) > 0              AND sil.STATUS IN ('A', 'C')         THEN 'SUBSTITUTE AVAILABLE'         WHEN NVL(sils.STOCK_ON_HAND, 0) = 0         THEN 'SUBSTITUTE OUT OF STOCK'         WHEN sil.STATUS NOT IN ('A', 'C')         THEN 'SUBSTITUTE ITEM/LOC NOT ACTIVE'         ELSE 'REVIEW REQUIRED'     END                                                  AS sub_availability_status,     ROUND(NVL(sil.SELLING_UNIT_RETAIL, 0)           - NVL(pil.SELLING_UNIT_RETAIL, 0), 2)         AS retail_price_difference,     CASE         WHEN pil.SELLING_UNIT_RETAIL > 0         THEN ROUND(              (NVL(sil.SELLING_UNIT_RETAIL, 0)               - NVL(pil.SELLING_UNIT_RETAIL, 0))              / pil.SELLING_UNIT_RETAIL * 100              , 2)     END                                                  AS retail_price_diff_pct FROM     MFCS_RDS.RDS_WV_SUB_ITEMS_DETAIL       sd     JOIN  MFCS_RDS.RDS_WV_SUB_ITEMS_HEAD   sh    ON  sd.ITEM      = sh.ITEM                                                   AND sd.LOCATION  = sh.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       pim   ON  sd.ITEM     = pim.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS              d     ON  pim.DEPT    = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS             c     ON  pim.DEPT    = c.DEPT                                                   AND pim.CLASS   = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc    ON  pim.DEPT    = sc.DEPT                                                   AND pim.CLASS   = sc.CLASS                                                   AND pim.SUBCLASS = sc.SUBCLASS     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       sim   ON  sd.SUB_ITEM = sim.ITEM     LEFT JOIN MFCS_RDS.RDS_WV_STORE         st    ON  sd.LOCATION = st.STORE                                                   AND sd.LOC_TYPE = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH            wh    ON  sd.LOCATION = wh.WH                                                   AND sd.LOC_TYPE = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      pil   ON  sd.ITEM     = pil.ITEM                                                   AND sd.LOCATION  = pil.LOC                                                   AND sd.LOC_TYPE  = pil.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  pils  ON  sd.ITEM     = pils.ITEM                                                   AND sd.LOCATION  = pils.LOC                                                   AND sd.LOC_TYPE  = pils.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      sil   ON  sd.SUB_ITEM = sil.ITEM                                                   AND sd.LOCATION  = sil.LOC                                                   AND sd.LOC_TYPE  = sil.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  sils  ON  sd.SUB_ITEM = sils.ITEM                                                   AND sd.LOCATION  = sils.LOC                                                   AND sd.LOC_TYPE  = sils.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC ril   ON  sd.ITEM     = ril.ITEM                                                   AND sd.LOCATION  = ril.LOCATION     LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC sril  ON  sd.SUB_ITEM = sril.ITEM                                                   AND sd.LOCATION  = sril.LOCATION WHERE     TRUNC(SYSDATE) >= NVL(sd.START_DATE, TRUNC(SYSDATE))     AND TRUNC(SYSDATE) <= NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999) ORDER BY     CASE         WHEN NVL(sils.STOCK_ON_HAND,0) > 0 AND sil.STATUS IN ('A','C')              THEN 'SUBSTITUTE AVAILABLE'         WHEN NVL(sils.STOCK_ON_HAND,0) = 0              THEN 'SUBSTITUTE OUT OF STOCK'         WHEN sil.STATUS NOT IN ('A','C')              THEN 'SUBSTITUTE ITEM/LOC NOT ACTIVE'         ELSE 'REVIEW REQUIRED'     END,     TRUNC(NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999)) - TRUNC(SYSDATE),     d.DEPT_NAME,     pim.ITEM_DESC,     CASE sd.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END